const softDeleteProductImages = `-- name: SoftDeleteProductImages :exec
UPDATE product_images
SET
    deleted_at = NOW(),
    updated_at = NOW()
WHERE product_images.product_id = $1
    AND product_images.deleted_at IS NULL
`

// === source: database/dml/repository/product/soft_delete_product_images.sql ===
// 商品が現在参照している画像をまとめて論理削除する。差し替えは「生存行を落として新しい行を入れる」形で
// 行うため、置換の前段としてここを通る。既に論理削除済みの行は削除日時を上書きしない。
// 生存行が無い商品に対しては 0 行更新となり、成功として返る。
//
//	UPDATE product_images
//	SET
//	    deleted_at = NOW(),
//	    updated_at = NOW()
//	WHERE product_images.product_id = $1
//	    AND product_images.deleted_at IS NULL
func (q *Queries) SoftDeleteProductImages(ctx context.Context, productID uuid.UUID) error {
	_, err := q.db.Exec(ctx, softDeleteProductImages, productID)
	return err
}

const updateProduct = `-- name: UpdateProduct :one
UPDATE products
SET
    name = $1,
    description = $2,
    price = $3,
    quantity = $4,
    stock_warning_threshold = $5,
    status_id = $6,
    category_id = $7,
    published_at = $8,
    lock_version = products.lock_version + 1,
    updated_at = NOW()
WHERE products.id = $9
    AND products.lock_version = $10
RETURNING products.lock_version
`

type UpdateProductParams struct {
	Name                  string
	Description           *string
	Price                 decimal.Decimal
	Quantity              int32
	StockWarningThreshold *int32
	StatusID              uuid.UUID
	CategoryID            uuid.UUID
	PublishedAt           *time.Time
	ID                    uuid.UUID
	CurrentVersion        int32
}

// === source: database/dml/repository/product/update_product.sql ===
// 楽観ロック条件付きで商品を更新し、採番後のバージョンを返します。
// lock_version の加算は DB が行い、採番の権威を単一箇所に置きます。
// WHERE の lock_version 一致が並行更新による lost update を防ぐ本体で、読み込み後に他トランザクションが
// 更新していた場合は該当行なし（0 行）で返り、呼び出し側が衝突として扱います。
//
//	UPDATE products
//	SET
//	    name = $1,
//	    description = $2,
//	    price = $3,
//	    quantity = $4,
//	    stock_warning_threshold = $5,
//	    status_id = $6,
//	    category_id = $7,
//	    published_at = $8,
//	    lock_version = products.lock_version + 1,
//	    updated_at = NOW()
//	WHERE products.id = $9
//	    AND products.lock_version = $10
//	RETURNING products.lock_version
func (q *Queries) UpdateProduct(ctx context.Context, arg *UpdateProductParams) (int32, error) {
	row := q.db.QueryRow(ctx, updateProduct,
		arg.Name,
		arg.Description,
		arg.Price,
		arg.Quantity,
		arg.StockWarningThreshold,
		arg.StatusID,
		arg.CategoryID,
		arg.PublishedAt,
		arg.ID,
		arg.CurrentVersion,
	)
	var lock_version int32
	err := row.Scan(&lock_version)
	return lock_version, err
}

const updateProductStock = `-- name: UpdateProductStock :one
UPDATE products
SET
    quantity = $1,
    lock_version = products.lock_version + 1,
    updated_at = NOW()
WHERE products.id = $2
    AND products.lock_version = $3
RETURNING products.lock_version
`

type UpdateProductStockParams struct {
	Quantity       int32
	ID             uuid.UUID
	CurrentVersion int32
}

// === source: database/dml/repository/product/update_product_stock.sql ===
// 在庫数を更新し、採番後のバージョンを返します。
// lock_version の加算は DB が行い、採番の権威を単一箇所に置きます。
// 在庫更新でもバージョンを進めることで、更新前のバージョンを条件とする部分更新（UpdateProduct）が
// 在庫の変化を上書きせずに 0 行で弾かれます。
// WHERE の lock_version 一致は、行ロックを取らずに呼ばれた場合に備える二重防御で、
// 該当行なし（0 行）は呼び出し側が衝突として扱います。
//
//	UPDATE products
//	SET
//	    quantity = $1,
//	    lock_version = products.lock_version + 1,
//	    updated_at = NOW()
//	WHERE products.id = $2
//	    AND products.lock_version = $3
//	RETURNING products.lock_version
func (q *Queries) UpdateProductStock(ctx context.Context, arg *UpdateProductStockParams) (int32, error) {
	row := q.db.QueryRow(ctx, updateProductStock, arg.Quantity, arg.ID, arg.CurrentVersion)
	var lock_version int32
	err := row.Scan(&lock_version)
	return lock_version, err
}
